</style>
<div id="hash-relaciona" style="font-family: Arial,Helvetica,sans-serif; max-width: 1100px; margin: 0 auto; color: #1f2937; line-height: 1.6;">
<div class="hr-header"><span class="hr-label">Estructuras de Datos en Python</span>
<h2>Juego de relacionar: Tablas Hash</h2>
<p style="margin: 0; color: #fff;">Relaciona los conceptos con sus definiciones y comprueba tus conocimientos de los seis subtemas.</p>
</div>
<div class="hr-intro"><strong>Indicaciones:</strong>
<p style="margin: 8px 0 0;">Lee cada concepto y selecciona la definición correcta en el menú desplegable. Cada relación correcta equivale a <strong>1 punto</strong>. Al finalizar, selecciona <strong>Comprobar respuestas</strong>.</p>
<p style="margin: 8px 0 0;">Puedes repetir la actividad las veces que necesites. En cada intento se mezclará el orden de las definiciones.</p>
</div>
<div class="hr-stats">
<div class="hr-stat"><strong id="hr-points">0/10</strong> <span>Puntuación</span></div>
<div class="hr-stat"><strong id="hr-answered">0/10</strong> <span>Respondidas</span></div>
<div class="hr-stat"><strong id="hr-attempts">0</strong> <span>Intentos realizados</span></div>
</div>
<div class="hr-progress" role="progressbar" aria-label="Preguntas respondidas" aria-valuemin="0" aria-valuemax="10" aria-valuenow="0" id="hr-progress">
<div class="hr-progress-bar" id="hr-progress-bar"></div>
</div>
<div id="hr-questions"></div>
<div class="hr-actions"><button type="button" class="hr-check" id="hr-check">Comprobar respuestas</button> <button type="button" class="hr-reset" id="hr-reset">Nuevo intento</button></div>
<div class="hr-result" id="hr-result" aria-live="polite">
<div style="font-size: 15px; font-weight: bold;">Resultado de la actividad</div>
<div class="hr-score" id="hr-final-score">0/10</div>
<p id="hr-final-message" style="margin: 12px 0 0;"></p>
<p id="hr-final-detail" style="margin: 8px 0 0; font-size: 14px; color: #4b5563;"></p>
</div>
<div class="hr-note"><strong>Criterios de evaluación:</strong> 10 relaciones correctas = 10 puntos. Cada error o respuesta sin seleccionar equivale a 0 puntos. La puntuación corresponde al intento actual y no existe límite de intentos.</div>
<div class="hr-footer"><strong style="color: #fbbf24;">Contenido evaluado</strong>
<p style="margin: 8px 0 0; color: #fff;">Fundamentos de tablas hash, funciones hash, colisiones, encadenamiento separado, direccionamiento abierto, factor de carga, operaciones fundamentales, diccionarios, implementación mediante clases y aplicaciones prácticas.</p>
</div>
<script>
(function () {
  "use strict";

  function iniciarJuegoHash() {
    var root = document.getElementById("hash-relaciona");
    if (!root || root.getAttribute("data-ready") === "1") return;
    root.setAttribute("data-ready", "1");

    var datos = [
      {
        id: 1,
        concepto: "Tabla hash",
        respuesta: "Estructura de datos que almacena información mediante pares clave-valor y permite búsquedas eficientes."
      },
      {
        id: 2,
        concepto: "Función hash",
        respuesta: "Procedimiento que transforma una clave en un valor numérico utilizado para calcular un índice de almacenamiento."
      },
      {
        id: 3,
        concepto: "Colisión",
        respuesta: "Situación en la que dos o más claves diferentes generan el mismo índice dentro de una tabla hash."
      },
      {
        id: 4,
        concepto: "Encadenamiento separado",
        respuesta: "Método de resolución de colisiones que almacena múltiples registros en una misma posición utilizando listas o nodos enlazados."
      },
      {
        id: 5,
        concepto: "Direccionamiento abierto",
        respuesta: "Método que resuelve colisiones buscando otra posición disponible dentro de la propia tabla."
      },
      {
        id: 6,
        concepto: "Factor de carga",
        respuesta: "Relación entre la cantidad de elementos almacenados y el número de posiciones disponibles en una tabla hash."
      },
      {
        id: 7,
        concepto: "Operaciones fundamentales",
        respuesta: "Acciones que permiten insertar, buscar, actualizar y eliminar registros mediante sus claves."
      },
      {
        id: 8,
        concepto: "Diccionario (dict)",
        respuesta: "Estructura integrada de Python que administra asociaciones clave-valor utilizando mecanismos hash."
      },
      {
        id: 9,
        concepto: "Clase HashTable",
        respuesta: "Implementación mediante programación orientada a objetos que encapsula el almacenamiento, la función hash y las operaciones de la tabla."
      },
      {
        id: 10,
        concepto: "Aplicaciones prácticas de las tablas hash",
        respuesta: "Uso de estructuras hash para gestionar inventarios, implementar cachés, contar frecuencias y detectar duplicados."
      }
    ];

    var preguntas = root.querySelector("#hr-questions");
    var puntos = root.querySelector("#hr-points");
    var respondidas = root.querySelector("#hr-answered");
    var intentos = root.querySelector("#hr-attempts");
    var progreso = root.querySelector("#hr-progress");
    var barra = root.querySelector("#hr-progress-bar");
    var resultado = root.querySelector("#hr-result");
    var notaFinal = root.querySelector("#hr-final-score");
    var mensajeFinal = root.querySelector("#hr-final-message");
    var detalleFinal = root.querySelector("#hr-final-detail");
    var btnComprobar = root.querySelector("#hr-check");
    var btnReiniciar = root.querySelector("#hr-reset");

    var numeroIntentos = 0;
    var evaluado = false;
    var opciones = [];

    function mezclar(elementos) {
      var copia = elementos.slice();

      for (var i = copia.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var temporal = copia[i];
        copia[i] = copia[j];
        copia[j] = temporal;
      }

      return copia;
    }

    function contarRespondidas() {
      var seleccionados = preguntas.querySelectorAll("select");
      var cantidad = 0;

      for (var i = 0; i < seleccionados.length; i++) {
        if (seleccionados[i].value !== "") cantidad++;
      }

      respondidas.textContent = cantidad + "/10";
      barra.style.width = (cantidad * 10) + "%";
      progreso.setAttribute("aria-valuenow", String(cantidad));
      return cantidad;
    }

    function crearJuego() {
      evaluado = false;
      opciones = mezclar(datos);
      preguntas.innerHTML = "";

      for (var i = 0; i < datos.length; i++) {
        var pregunta = datos[i];

        var tarjeta = document.createElement("div");
        tarjeta.className = "hr-item";

        var numero = document.createElement("div");
        numero.className = "hr-number";
        numero.textContent = "Elemento " + (i + 1);

        var concepto = document.createElement("div");
        concepto.className = "hr-concept";
        concepto.textContent = pregunta.concepto;

        var selector = document.createElement("select");
        selector.id = "hr-select-" + pregunta.id;
        selector.setAttribute("aria-label", "Definición de " + pregunta.concepto);
        selector.setAttribute("data-correct", String(pregunta.id));

        var vacio = document.createElement("option");
        vacio.value = "";
        vacio.textContent = "Selecciona la definición correcta...";
        selector.appendChild(vacio);

        for (var j = 0; j < opciones.length; j++) {
          var opcion = document.createElement("option");
          opcion.value = String(opciones[j].id);
          opcion.textContent = opciones[j].respuesta;
          selector.appendChild(opcion);
        }

        selector.addEventListener("change", function () {
          if (evaluado) {
            evaluado = false;
            puntos.textContent = "0/10";
            resultado.style.display = "none";

            var tarjetas = preguntas.querySelectorAll(".hr-item");
            for (var n = 0; n < tarjetas.length; n++) {
              tarjetas[n].classList.remove("hr-correct", "hr-wrong");
              tarjetas[n].querySelector(".hr-feedback").textContent = "";
            }
          }
          contarRespondidas();
        });

        var feedback = document.createElement("div");
        feedback.className = "hr-feedback";
        feedback.setAttribute("aria-live", "polite");

        tarjeta.appendChild(numero);
        tarjeta.appendChild(concepto);
        tarjeta.appendChild(selector);
        tarjeta.appendChild(feedback);
        preguntas.appendChild(tarjeta);
      }

      puntos.textContent = "0/10";
      respondidas.textContent = "0/10";
      barra.style.width = "0%";
      progreso.setAttribute("aria-valuenow", "0");
      resultado.style.display = "none";
    }

    function comprobar() {
      var tarjetas = preguntas.querySelectorAll(".hr-item");
      var aciertos = 0;
      var noRespondidas = 0;

      for (var i = 0; i < tarjetas.length; i++) {
        var tarjeta = tarjetas[i];
        var selector = tarjeta.querySelector("select");
        var feedback = tarjeta.querySelector(".hr-feedback");
        var correcta = selector.getAttribute("data-correct");

        tarjeta.classList.remove("hr-correct", "hr-wrong");
        feedback.textContent = "";

        if (selector.value === correcta) {
          aciertos++;
          tarjeta.classList.add("hr-correct");
          feedback.style.color = "#047857";
          feedback.textContent = "✓ Correcto. Relación acertada.";
        } else {
          tarjeta.classList.add("hr-wrong");
          feedback.style.color = "#B91C1C";

          if (selector.value === "") {
            noRespondidas++;
            feedback.textContent = "✗ Sin respuesta. ";
          } else {
            feedback.textContent = "✗ Relación incorrecta. ";
          }

          feedback.appendChild(document.createTextNode("Respuesta correcta: " + datos[i].respuesta));
        }
      }

      numeroIntentos++;
      evaluado = true;

      puntos.textContent = aciertos + "/10";
      intentos.textContent = String(numeroIntentos);
      notaFinal.textContent = aciertos + "/10";
      contarRespondidas();

      if (aciertos === 10) {
        mensajeFinal.textContent = "¡Excelente! Has relacionado correctamente todos los conceptos.";
        notaFinal.style.color = "#047857";
      } else if (aciertos >= 8) {
        mensajeFinal.textContent = "¡Muy buen resultado! Revisa las relaciones que necesitan corrección.";
        notaFinal.style.color = "#047857";
      } else if (aciertos >= 6) {
        mensajeFinal.textContent = "Buen avance. Repasa los conceptos en los que tuviste dificultades.";
        notaFinal.style.color = "#2563EB";
      } else {
        mensajeFinal.textContent = "Es recomendable revisar nuevamente los conceptos y realizar otro intento.";
        notaFinal.style.color = "#B45309";
      }

      detalleFinal.textContent =
        "Aciertos: " + aciertos +
        " | Incorrectas: " + (10 - aciertos - noRespondidas) +
        " | Sin responder: " + noRespondidas +
        " | Intento: " + numeroIntentos;

      resultado.style.display = "block";
    }

    btnComprobar.addEventListener("click", comprobar);
    btnReiniciar.addEventListener("click", crearJuego);

    crearJuego();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", iniciarJuegoHash);
  } else {
    iniciarJuegoHash();
  }
})();
</script>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
